from collections import defaultdict

def over_limit(requests, window=3, limit=2):
    by_client = defaultdict(list)
    for client, ts in requests:
        by_client[client].append(ts)
    bad = []
    for client, times in by_client.items():
        times.sort()
        lo = hi = 0
        for t0 in times:
            while hi < len(times) and times[hi] < t0 + window:
                hi += 1
            while lo < hi and times[lo] < t0:
                lo += 1
            if hi - lo > limit:
                bad.append(client)
                break
    return sorted(bad)

def _part(p):
    return base64.urlsafe_b64decode(p + '=' * (-len(p) % 4))

def decode_payload(token):
    parts = token.split('.')
    if len(parts) < 2:
        return None
    try:
        return json.loads(_part(parts[1]))
    except Exception:
        return None

def is_unsigned(token):
    parts = token.split('.')
    if not parts or not parts[0]:
        return False
    try:
        return json.loads(_part(parts[0])).get('alg') == 'none'
    except Exception:
        return False

from collections import Counter

def top_ips(lines, threshold=1):
    counts = Counter()
    for line in lines:
        parts = line.split()
        if not parts:
            continue
        ip = parts[0]
        if ip.count('.') != 3:
            continue
        counts[ip] += 1
    out = [(ip, n) for ip, n in counts.items() if n > threshold]
    return sorted(out, key=lambda kv: -kv[1])

